grW(){return"\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u044d\u043a\u0440\u0430\u043d, \u043a\u0430\u043a \u0432\u044b \u0442\u0440\u0435\u043d\u0438\u0440\u0443\u0435\u0442\u0435\u0441\u044c, \u0438 \u043f\u043e\u0447\u0435\u043c\u0443 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0435 \u0443\u0447\u0438\u0442 \u0432\u0430\u0441 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u0441\u044f."},
grZ(){return"\u0418\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u044b"},
grY(){return"\u0420\u0438\u0442\u043c, \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435, \u0433\u0440\u0443\u043f\u043f\u044b \u043c\u044b\u0448\u0446 \u0438 \u0431\u044b\u0441\u0442\u0440\u0430\u044f \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0430."},
grV(){return"\u041d\u0430 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0435"},
grU(){return"\u041f\u043e\u0434\u0445\u043e\u0434\u044b, \u043f\u043e\u043b\u044f, \u043a\u0430\u0440\u0434\u0438\u043e, \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u0438 \u0441\u0435\u043a\u0443\u043d\u0434\u043e\u043c\u0435\u0440."},
